                room.getType().name(),
                reservation.getId(),
                reservation.getCheckIn().format(DATE_FORMAT),
                reservation.getCheckOut().format(DATE_FORMAT)
            ));
        }

        csv.append(String.format("total,%d/%d", reservations.size(), TOTAL_ROOMS));

        return csv.toString();
    }
}

